import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import pytest

from versions import latest, sort_versions


def parse_key(v):
    v = v.lstrip("v")
    parts = [int(p) for p in v.split(".")]
    while len(parts) < 3:
        parts.append(0)
    return tuple(parts)


class TestLatest:
    def test_lexicographic_bug(self):
        assert latest(["1.9.0", "1.10.0"]) == "1.10.0"

    def test_v_prefix(self):
        assert latest(["v1.9.0", "v1.10.0"]) == "v1.10.0"

    def test_missing_parts(self):
        assert latest(["1.2", "1.2.0"]) in ("1.2", "1.2.0")
        assert latest(["1.9", "1.10.0"]) == "1.10.0"

    def test_empty_raises(self):
        with pytest.raises(ValueError):
            latest([])


class TestSortVersions:
    def test_mixed(self):
        assert sort_versions(["2.0.0", "1.10.0", "1.9.0", "1.2.10"]) == [
            "1.2.10",
            "1.9.0",
            "1.10.0",
            "2.0.0",
        ]

    def test_v_prefix_and_short(self):
        assert sort_versions(["v1.10.0", "1.9", "1.2.3"]) == ["1.2.3", "1.9", "v1.10.0"]


def test_randomized_against_tuple_comparison():
    rng = random.Random(42)
    for _ in range(200):
        n = rng.randint(1, 20)
        versions = [
            "{}{}.{}.{}".format(
                "v" if rng.random() < 0.3 else "",
                rng.randint(0, 5),
                rng.randint(0, 15),
                rng.randint(0, 20),
            )
            for _ in range(n)
        ]
        shuffled = versions[:]
        rng.shuffle(shuffled)
        expected = sorted(versions, key=parse_key)
        assert sort_versions(shuffled) == expected
