    """Sort key for dotted version strings like '1.10.0', 'v2.3', '1.2'.

    Strips an optional leading 'v', splits on '.', converts each part to int,
    and pads missing parts with 0 so '1.2' orders like '1.2.0'.
    """
    parts = version.strip().lstrip("v").split(".")
    key = tuple(int(p) for p in parts)
    # pad to 3 components: (major, minor, patch)
    return key + (0,) * (3 - len(key))


def latest(versions):
    """Return the newest version string from a list like ['1.9.0', '1.10.0']."""
    if not versions:
        raise ValueError("latest() arg is an empty sequence")
    return max(versions, key=_version_key)


def sort_versions(versions):
    """Return versions sorted oldest to newest using numeric comparison."""
    return sorted(versions, key=_version_key)
